package com.afirma.assina;
import java.util.*;
import java.net.URI;
import java.net.http.*;
import java.time.Duration;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.multipart.MultipartFile;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.JsonNode;

/** Componentes, exemplos, atualização e mídia de templates do contrato Autentica. */
@Service
public class TemplatesMetaAutentica {
 private final BancoAssineai banco;private final AutenticaPersistencia persistencia;private final ServicoCanalOficial oficial;private final ObjectMapper json;private final String versao;
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();
 public TemplatesMetaAutentica(BancoAssineai banco,AutenticaPersistencia persistencia,ServicoCanalOficial oficial,ObjectMapper json,@Value("${APP_META_VERSAO:v23.0}")String versao){this.banco=banco;this.persistencia=persistencia;this.oficial=oficial;this.json=json;this.versao=versao;}
 static List<Object> exemplos(Object valores){var r=new ArrayList<Object>();if(valores instanceof List<?> l)for(var v:l)if(v instanceof Map<?,?> m)r.add(m.getOrDefault("Valor",null));return r;}
 static List<Map<String,Object>> componentes(Map<String,Object> r){var lista=new ArrayList<Map<String,Object>>();String tipo=Objects.toString(r.get("MensagemTemplateCabecalhoTipo"),"");var conteudo=r.get("MensagemTemplateCabecalhoConteudo") instanceof Map<?,?> m?m:Map.of();
  if(tipo.equals("Texto")){var h=new HashMap<String,Object>(Map.of("type","HEADER","format","TEXT","text",Objects.toString(conteudo.get("Texto"),"")));var exemplo=exemplos(r.get("MensagemTemplateCabecalhoVariaveis"));if(!exemplo.isEmpty())h.put("example",Map.of("header_text",exemplo));lista.add(h);}
  else if(Set.of("Imagem","Vídeo","Documento").contains(tipo)){String handle=Objects.toString(conteudo.get("MediaHandle"),"");RegrasAutentica.exigir(!handle.isBlank(),"Envie o exemplo de mídia do cabeçalho antes de publicar");lista.add(Map.of("type","HEADER","format",switch(tipo){case "Imagem"->"IMAGE";case "Vídeo"->"VIDEO";default->"DOCUMENT";},"example",Map.of("header_handle",List.of(handle))));}
  var b=new HashMap<String,Object>(Map.of("type","BODY","text",Objects.toString(r.get("MensagemTemplateCorpo"),"")));var exemplos=exemplos(r.get("MensagemTemplateCorpoVariaveis"));if(!exemplos.isEmpty())b.put("example",Map.of("body_text",List.of(exemplos)));lista.add(b);
  if(r.get("MensagemTemplateRodape") instanceof String f&&!f.isBlank())lista.add(Map.of("type","FOOTER","text",f));
  if(r.get("MensagemTemplateBotoes") instanceof List<?> botoes&&!botoes.isEmpty()){RegrasAutentica.exigir(botoes.size()<=10,"Muitos botões");var bs=new ArrayList<Map<String,Object>>();for(var botao:botoes){RegrasAutentica.exigir(botao instanceof Map<?,?>,"Botão inválido");var m=(Map<?,?>)botao;String texto=Objects.toString(m.get("Texto"),"");RegrasAutentica.exigir(!texto.isBlank(),"Informe o texto do botão");switch(Objects.toString(m.get("Tipo"),"")){case "quick-reply"->bs.add(Map.of("type","QUICK_REPLY","text",texto));case "call-phone"->bs.add(Map.of("type","PHONE_NUMBER","text",texto,"phone_number",Objects.toString(m.get("CodigoPais"),"")+Objects.toString(m.get("Numero"),"")));case "visit-website"->{String url=Objects.toString(m.get("URL"),"");RegrasAutentica.url(url.replace("{{1}}","exemplo"));bs.add(Map.of("type","URL","text",texto,"url",url));}default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tipo de botão inválido");}}lista.add(Map.of("type","BUTTONS","buttons",bs));}return lista;
 }
 private JsonNode chamar(long cliente,String metodo,String caminho,Object corpo){String token=oficial.tokenAutentica(cliente);try{var req=HttpRequest.newBuilder(URI.create("https://graph.facebook.com/"+versao+"/"+caminho)).timeout(Duration.ofSeconds(30)).header("Authorization","Bearer "+token).header("Content-Type","application/json").method(metodo,corpo==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(corpo)));var r=http.send(req.build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>=300)throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"A Meta recusou a operação do template (HTTP "+r.statusCode()+")");return json.readTree(r.body());}catch(ResponseStatusException e){throw e;}catch(Exception e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Meta indisponível");}}
 public Object operar(long id,String acao,long cliente){var r=banco.um("SELECT * FROM autentica.\"MensagemTemplate\" WHERE id=:id AND \"ClienteId\"=:c",Map.of("id",id,"c",cliente));if(r==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);var canal=banco.um("SELECT * FROM autentica.\"Canal\" WHERE id=:id AND \"ClienteId\"=:c AND \"CanalProvedorAPI\"='Meta'",Map.of("id",OperacaoAutentica.numero(r,"CanalId"),"c",cliente));if(canal==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Canal oficial não encontrado");String conta=Objects.toString(canal.get("CanalMetaWAID"),"");RegrasAutentica.exigir(conta.matches("[0-9]{5,30}"),"Informe o identificador da conta Meta no canal");String remoto=Objects.toString(r.get("MensagemTemplateMetaId"),"");JsonNode resposta;
  if(acao.equals("publicar")){var corpo=new HashMap<String,Object>(Map.of("category",r.get("MensagemTemplateCategoria"),"components",componentes(r)));String caminho=remoto;if(remoto.isBlank()){corpo.put("name",r.get("MensagemTemplateNome"));corpo.put("language","pt_BR");corpo.put("allow_category_change",false);caminho=conta+"/message_templates";}else RegrasAutentica.exigir(remoto.matches("[0-9]{5,30}"),"Identificador de template inválido");resposta=chamar(cliente,"POST",caminho,corpo);String codigo=resposta.path("id").asText(remoto);RegrasAutentica.exigir(codigo.matches("[0-9]{5,30}"),"A Meta não confirmou o identificador do template");persistencia.gravar("MensagemTemplate",id,Map.of("MensagemTemplateMetaId",codigo,"MensagemTemplateStatusMeta",resposta.path("status").asText("PENDING")));}
  else if(acao.equals("sincronizar")){if(remoto.isBlank()){var consulta=chamar(cliente,"GET",conta+"/message_templates?fields=id,status,rejected_reason&name="+r.get("MensagemTemplateNome"),null);RegrasAutentica.exigir(consulta.path("data").size()>0,"Template não encontrado na Meta");resposta=consulta.path("data").path(0);}else{RegrasAutentica.exigir(remoto.matches("[0-9]{5,30}"),"Identificador de template inválido");resposta=chamar(cliente,"GET",remoto+"?fields=id,status,rejected_reason",null);}var v=new HashMap<String,Object>();v.put("MensagemTemplateMetaId",resposta.path("id").asText(remoto));v.put("MensagemTemplateStatusMeta",resposta.path("status").asText("PENDING"));v.put("MensagemTemplateMotivoRejeicaoMeta",resposta.path("rejected_reason").asText(null));persistencia.gravar("MensagemTemplate",id,v);}
  else if(acao.equals("excluir-meta")){resposta=chamar(cliente,"DELETE",conta+"/message_templates?name="+r.get("MensagemTemplateNome"),null);persistencia.gravar("MensagemTemplate",id,Map.of("MensagemTemplateStatusUso",false));}
  else throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Ação inválida");return Map.of("sucesso",true,"status",resposta.path("status").asText("PENDING"));
 }
 public String media(long cliente,MultipartFile arquivo){RegrasAutentica.exigir(arquivo!=null&&!arquivo.isEmpty()&&arquivo.getSize()<=15*1024*1024,"Mídia inválida");var empresa=banco.um("SELECT \"ClienteMetaIdAplicativo\" FROM autentica.\"Cliente\" WHERE id=:id",Map.of("id",cliente));String app=Objects.toString(empresa.get("ClienteMetaIdAplicativo"),"");RegrasAutentica.exigir(app.matches("[0-9]{5,30}"),"Informe o aplicativo Meta no cadastro da empresa");String tipo=Objects.toString(arquivo.getContentType(),"application/octet-stream"),nome=Objects.toString(arquivo.getOriginalFilename(),"exemplo");String consulta="?file_name="+java.net.URLEncoder.encode(nome,java.nio.charset.StandardCharsets.UTF_8)+"&file_length="+arquivo.getSize()+"&file_type="+java.net.URLEncoder.encode(tipo,java.nio.charset.StandardCharsets.UTF_8);String sessao=chamar(cliente,"POST",app+"/uploads"+consulta,null).path("id").asText();RegrasAutentica.exigir(sessao.matches("[A-Za-z0-9:_=+%?&.\\/-]{1,2000}"),"Sessão de upload inválida");try{var req=HttpRequest.newBuilder(URI.create("https://graph.facebook.com/"+versao+"/"+sessao)).timeout(Duration.ofSeconds(60)).header("Authorization","OAuth "+oficial.tokenAutentica(cliente)).header("file_offset","0").header("Content-Type",tipo).POST(HttpRequest.BodyPublishers.ofByteArray(arquivo.getBytes())).build();var r=http.send(req,HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException();String h=json.readTree(r.body()).path("h").asText();RegrasAutentica.exigir(!h.isBlank(),"A Meta não confirmou a mídia");return h;}catch(Exception e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Upload de exemplo indisponível");}}
}
